<?php
namespace Tests\Feature;use App\Actions\CreateServiceRequestAction;use App\Models\{Department,GuestSession,Hotel,Service,ServiceCategory};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class ServiceRoutingTest extends TestCase{use RefreshDatabase;public function test_service_request_derives_department_and_sla_from_server_data():void{$h=Hotel::create(['name'=>'H','slug'=>'h','timezone'=>'UTC','status'=>'active']);$d=Department::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'name'=>'Housekeeping','code'=>'HK','is_active'=>true]);$c=ServiceCategory::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'name'=>'Guest','slug'=>'guest','is_active'=>true]);$s=Service::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'service_category_id'=>$c->id,'department_id'=>$d->id,'name'=>'Towels','slug'=>'towels','target_response_minutes'=>10,'target_completion_minutes'=>20,'is_active'=>true]);$qr=\DB::table('qr_codes')->insertGetId(['hotel_id'=>$h->id,'public_token'=>str_repeat('z',48),'qrable_type'=>Hotel::class,'qrable_id'=>$h->id,'is_active'=>1,'created_at'=>now(),'updated_at'=>now()]);$g=GuestSession::withoutGlobalScopes()->create(['hotel_id'=>$h->id,'qr_code_id'=>$qr,'public_id'=>str_repeat('g',48),'expires_at'=>now()->addHour(),'status'=>'active']);$r=app(CreateServiceRequestAction::class)->execute($g,['service_id'=>$s->id]);$this->assertSame($d->id,$r->department_id);$this->assertEqualsWithDelta(20,now()->diffInMinutes($r->completion_due_at,false),1);}}
